//
// Known-answer tests: the TypeScript channel must reproduce the
// PYTHON implementation's bytes exactly (vectors generated by
// scripts/make_channel_vectors.py from nrupala/mykey's
// native_host.py; CI regenerates and diffs). If these fail, the
// extension and the desktop cannot talk — and a silent format
// drift here is exactly how "encrypted" channels quietly break.

import { describe, expect, it } from "vitest";
import { x25519 } from "@noble/curves/ed25519.js";
import {
  deriveSessionKeys,
  keyFingerprint,
  openMessage,
  sealMessage,
  type SealedFrame,
} from "../src/channel.js";
import { b64decode } from "../../src/vault/encoding.js";
import vectors from "./fixtures/channel-vectors.json";

function sessionKeys(): { e2h: Uint8Array; h2e: Uint8Array } {
  const shared = x25519.getSharedSecret(
    b64decode(vectors.ext_priv_b64),
    b64decode(vectors.host_pub_b64),
  );
  return deriveSessionKeys(
    shared,
    b64decode(vectors.client_nonce_b64),
    b64decode(vectors.server_nonce_b64),
  );
}

describe("channel known-answer vectors (python oracle)", () => {
  it("derives the same session keys", () => {
    const keys = sessionKeys();
    expect(Buffer.from(keys.e2h).toString("hex")).toBe(vectors.keys.e2h);
    expect(Buffer.from(keys.h2e).toString("hex")).toBe(vectors.keys.h2e);
  });

  it("seals e2h messages byte-for-byte like python", async () => {
    const keys = sessionKeys();
    for (const [i, entry] of vectors.e2h.entries()) {
      const frame = await sealMessage(
        keys.e2h,
        "e2h",
        vectors.session_id,
        i,
        entry.message as Record<string, unknown>,
      );
      expect(frame).toEqual(entry.frame);
    }
  });

  it("opens the python host's h2e frames", async () => {
    const keys = sessionKeys();
    for (const entry of vectors.h2e) {
      const message = await openMessage(
        keys.h2e,
        "h2e",
        vectors.session_id,
        entry.frame as SealedFrame,
      );
      expect(message).toEqual(entry.message);
    }
  });

  it("rejects a tampered frame and a sequence-shifted frame", async () => {
    const keys = sessionKeys();
    const frame = vectors.h2e[0]!.frame as SealedFrame;
    const tampered: SealedFrame = {
      ...frame,
      ct: `${frame.ct.slice(0, -2)}AA`,
    };
    await expect(
      openMessage(keys.h2e, "h2e", vectors.session_id, tampered),
    ).rejects.toThrow();
    const shifted: SealedFrame = { ...frame, seq: frame.seq + 5 };
    await expect(
      openMessage(keys.h2e, "h2e", vectors.session_id, shifted),
    ).rejects.toThrow(/nonce|sequence/);
    const wrongSession: SealedFrame = { ...frame, session: "0".repeat(32) };
    await expect(
      openMessage(keys.h2e, "h2e", vectors.session_id, wrongSession),
    ).rejects.toThrow(/session/);
  });

  it("fingerprints a key the same way on both sides", () => {
    const fp = keyFingerprint(b64decode(vectors.host_pub_b64));
    expect(fp).toMatch(/^[0-9a-f]{4}(:[0-9a-f]{4}){7}$/);
  });
});
